-- Executar depois de supabase.sql. Migração adicional para /admin completo.
begin;
alter table public.profiles add column if not exists active boolean not null default true;
create or replace function public.account_enabled() returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select 1 from public.profiles where id=auth.uid() and active);$$;
revoke all on function public.account_enabled() from public;grant execute on function public.account_enabled() to authenticated;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select 1 from public.app_admins a join public.profiles p on p.id=a.user_id where a.user_id=auth.uid() and p.active);$$;

create table if not exists public.site_settings(id integer primary key check(id=1),config jsonb not null default '{}'::jsonb check(jsonb_typeof(config)='object'),revision integer not null default 1,updated_at timestamptz not null default now());
insert into public.site_settings(id) values(1) on conflict(id) do nothing;
create table if not exists public.site_revisions(id bigint generated by default as identity primary key,config jsonb not null,revision integer not null,actor_id uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.audit_logs(id bigint generated by default as identity primary key,actor_id uuid,action text not null,entity text not null,entity_id text,created_at timestamptz not null default now());
create table if not exists public.product_files(id bigint generated by default as identity primary key,product_id bigint not null references public.products(id),name text not null check(char_length(name) between 1 and 180),path text not null unique check(path ~ '^[0-9]+/[a-f0-9-]+\.zip$'),size bigint not null check(size between 1 and 26214400),created_at timestamptz not null default now());
alter table public.site_settings enable row level security;
alter table public.site_revisions enable row level security;
alter table public.audit_logs enable row level security;
alter table public.product_files enable row level security;
revoke all on public.site_settings,public.site_revisions,public.audit_logs,public.product_files from anon,authenticated;
grant select on public.site_settings to anon,authenticated;
grant select on public.site_revisions,public.audit_logs,public.product_files to authenticated;
grant insert,update,delete on public.product_files to authenticated;
grant usage,select on all sequences in schema public to authenticated;
create policy settings_public on public.site_settings for select to anon,authenticated using(true);
create policy revisions_admin on public.site_revisions for select to authenticated using(public.is_admin());
create policy audit_admin on public.audit_logs for select to authenticated using(public.is_admin());
create policy files_owner on public.product_files for select to authenticated using(public.is_admin() or (public.account_enabled() and exists(select 1 from public.licenses l where l.product_id=product_files.product_id and l.user_id=auth.uid() and l.status='active' and (l.expires_at is null or l.expires_at>=current_date))));
create policy files_admin on public.product_files for all to authenticated using(public.is_admin()) with check(public.is_admin());

-- Clientes bloqueados não acessam dados mesmo com um JWT de sessão antigo.
drop policy if exists profile_read on public.profiles;
create policy profile_read on public.profiles for select to authenticated using((id=auth.uid() and active) or public.is_admin());
drop policy if exists profile_write on public.profiles;
create policy profile_write on public.profiles for update to authenticated using(id=auth.uid() and active) with check(id=auth.uid() and active);
drop policy if exists orders_read on public.orders;
create policy orders_read on public.orders for select to authenticated using((user_id=auth.uid() and public.account_enabled()) or public.is_admin());
drop policy if exists licenses_read on public.licenses;
create policy licenses_read on public.licenses for select to authenticated using((user_id=auth.uid() and public.account_enabled()) or public.is_admin());
drop policy if exists tickets_read on public.tickets;
create policy tickets_read on public.tickets for select to authenticated using((user_id=auth.uid() and public.account_enabled()) or public.is_admin());
drop policy if exists messages_read on public.messages;
create policy messages_read on public.messages for select to authenticated using(public.is_admin() or (public.account_enabled() and exists(select 1 from public.tickets t where t.id=ticket_id and t.user_id=auth.uid())));
drop policy if exists briefings_read on public.briefings;
create policy briefings_read on public.briefings for select to authenticated using((user_id=auth.uid() and public.account_enabled()) or public.is_admin());
drop policy if exists briefings_insert on public.briefings;
create policy briefings_insert on public.briefings for insert to authenticated with check(user_id=auth.uid() and public.account_enabled());

create or replace function public.valid_site_url(v text) returns boolean language sql immutable set search_path=public,pg_temp as $$select v is not null and char_length(v)<=2000 and (v ~ '^https://[^[:space:]]+$' or (v ~ '^(#|[a-zA-Z0-9_.-]+(/|\.html|#|\?))' and position('..' in v)=0 and position(':' in v)=0 and position(chr(92) in v)=0 and left(v,2)<>'//'));$$;
revoke all on function public.valid_site_url(text) from public;
create or replace function public.admin_save_site(p_config jsonb,p_revision integer) returns integer language plpgsql security definer set search_path=public,pg_temp as $$
declare r integer;item jsonb;k text;sz numeric;begin
if not public.is_admin() then raise exception 'permission_denied';end if;
if p_config is null or jsonb_typeof(p_config)<>'object' or octet_length(p_config::text)>200000 then raise exception 'invalid_config';end if;
if char_length(coalesce(p_config#>>'{branding,name}','')) not between 1 and 100 then raise exception 'invalid_brand';end if;
foreach k in array array['accent','background','surface','text','muted'] loop if coalesce(p_config#>>array['branding',k],'') !~ '^#[0-9A-Fa-f]{6}$' then raise exception 'invalid_color';end if;end loop;
if coalesce(p_config#>>'{branding,font}','') not in ('inter','manrope','jakarta') then raise exception 'invalid_font';end if;
foreach k in array array['bodySize','headingSize','tracking'] loop if coalesce(p_config#>>array['branding',k],'') !~ '^[0-9]+(\.[0-9]+)?$' then raise exception 'invalid_size';end if;sz=(p_config#>>array['branding',k])::numeric;if (k='bodySize' and (sz<16 or sz>22)) or (k='headingSize' and (sz<38 or sz>72)) or (k='tracking' and (sz<0 or sz>1)) then raise exception 'invalid_size';end if;end loop;
foreach k in array array['navigation','plans','faq','features'] loop if jsonb_typeof(p_config->k)<>'array' then raise exception 'invalid_collection';end if;end loop;
if jsonb_array_length(p_config->'navigation')>12 or jsonb_array_length(p_config->'plans')>8 or jsonb_array_length(p_config->'faq')>30 or jsonb_array_length(p_config->'features')>12 then raise exception 'collection_limit';end if;
for item in select value from jsonb_array_elements(p_config->'navigation') loop if not public.valid_site_url(item->>'url') then raise exception 'invalid_link';end if;end loop;
if not public.valid_site_url(p_config#>>'{hero,primaryUrl}') or not public.valid_site_url(p_config#>>'{hero,secondaryUrl}') or not public.valid_site_url(p_config#>>'{cta,url}') then raise exception 'invalid_link';end if;
foreach k in array array['branding.logoUrl','hero.imageUrl','contact.discord'] loop if coalesce(p_config#>>string_to_array(k,'.'),'')<>'' and coalesce(p_config#>>string_to_array(k,'.'),'') !~ '^https://[^[:space:]]+$' then raise exception 'invalid_media_url';end if;end loop;
select revision into r from public.site_settings where id=1 for update;
if r is distinct from p_revision then raise exception 'revision_conflict';end if;
insert into public.site_revisions(config,revision,actor_id) select config,revision,auth.uid() from public.site_settings where id=1;
update public.site_settings set config=p_config,revision=r+1,updated_at=now() where id=1;
insert into public.audit_logs(actor_id,action,entity,entity_id) values(auth.uid(),'publish','site_settings','1');return r+1;
end;$$;
revoke all on function public.admin_save_site(jsonb,integer) from public;grant execute on function public.admin_save_site(jsonb,integer) to authenticated;

create or replace function public.audit_change() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin insert into public.audit_logs(actor_id,action,entity,entity_id) values(auth.uid(),lower(TG_OP),TG_TABLE_NAME,case when TG_OP='DELETE' then old.id::text else new.id::text end);return case when TG_OP='DELETE' then old else new end;end;$$;
revoke all on function public.audit_change() from public;
create trigger audit_products after insert or update or delete on public.products for each row execute function public.audit_change();
create trigger audit_orders after insert or update on public.orders for each row execute function public.audit_change();
create trigger audit_licenses after insert or update on public.licenses for each row execute function public.audit_change();
create trigger audit_content after insert or update or delete on public.content for each row execute function public.audit_change();
create trigger audit_files after insert or update or delete on public.product_files for each row execute function public.audit_change();

-- Guardas no servidor para cadastro pausado e contas bloqueadas.
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin
if (select config#>>'{operation,allowRegistration}' from public.site_settings where id=1)='false' and coalesce(new.raw_app_meta_data->>'s7ven_admin_created','false')<>'true' then raise exception 'registration_paused';end if;
insert into public.profiles(id,display_name,email) values(new.id,coalesce(nullif(left(trim(new.raw_user_meta_data->>'display_name'),100),''),'Cliente'),coalesce(new.email,''));return new;end;$$;
create or replace function public.guard_write_account() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin if auth.uid() is not null and not public.account_enabled() then raise exception 'account_disabled';end if;return new;end;$$;
revoke all on function public.guard_write_account() from public;
create trigger guard_orders before insert on public.orders for each row execute function public.guard_write_account();
create trigger guard_tickets before insert on public.tickets for each row execute function public.guard_write_account();
create trigger guard_messages before insert on public.messages for each row execute function public.guard_write_account();
commit;
